<?php

declare(strict_types=1);

namespace Plagx\Preflight\Tests;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use Plagx\Preflight\Preflight;

/**
 * tests/parity/expected.json is generated by the JavaScript reference
 * (plagx-preflight, npm run parity). Every case must match exactly.
 */
final class ParityTest extends TestCase
{
    private static ?array $data = null;

    private static function data(): array
    {
        return self::$data ??= json_decode(file_get_contents(__DIR__ . '/parity/expected.json'), true, 512, JSON_THROW_ON_ERROR);
    }

    public static function cases(): iterable
    {
        foreach (self::data()['cases'] as $case) {
            yield "{$case['fixture']} / {$case['options']}" => [$case['fixture'], $case['options'], $case['result']];
        }
    }

    #[DataProvider('cases')]
    public function testMatchesJavaScript(string $fixture, string $optionSet, array $expected): void
    {
        $text = file_get_contents(__DIR__ . "/fixtures/{$fixture}");
        $options = self::data()['optionSets'][$optionSet];
        $flags = JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT;
        $this->assertSame(json_encode($expected, $flags), json_encode(Preflight::checkDraft($text, $options), $flags));
    }

    public function testCoversEveryFixture(): void
    {
        $this->assertCount(160, self::data()['cases']);
        $this->assertSame(Preflight::VERSION, self::data()['version']);
    }
}
